// Auto-extracted from the original monolithic app.js.
// Each module exports a slice of the global `app` object; main.js merges them.
export const utils = {
  abortRequest(key) {
    const ctrl = this.abortControllers.get(key);
    if (ctrl) { ctrl.abort(); this.abortControllers.delete(key); }
  },

  paperSource(id) {
    if (this.insightPageId === id && this.insightPageSource) return this.insightPageSource;
    if (this.insightPageData && this.insightPageData.id === id) return this.insightPageData.source_type || 'arxiv';
    if (this.data && this.data.papers) {
      const p = this.data.papers.find(p => p.id === id);
      if (p) return p.source_type || 'arxiv';
    }
    if (this.datesPapers) {
      const p = this.datesPapers.find(p => p.id === id);
      if (p) return p.source_type || 'arxiv';
    }
    if (this.tagsData) {
      for (const tag of Object.values(this.tagsData)) {
        if (tag.papers) {
          const p = tag.papers.find(p => p.id === id);
          if (p) return p.source_type || 'arxiv';
        }
      }
    }
    return 'arxiv';
  },

  isCurrentInsight(id, source) {
    if (this.insightPageId !== id) return false;
    return !source || !this.insightPageSource || this.insightPageSource === source;
  },

  isMarkdown(text) {
    return /#{1,6}\s|```|\*\*|__|~~|>|`[^`]+`|\[.+\]\(.+\)|!\[.+\]\(.+\)|\|.+\||^\s*[-*+]\s/m.test(text);
  },

  truncateText(text, maxLen = 200) {
    if (text.length <= maxLen) return text;
    let end = maxLen;
    while (end > maxLen - 50 && text[end] !== ' ' && text[end] !== '\n') end--;
    return text.slice(0, end) + '...';
  },

  isImageQuote(quote) {
    return quote && (quote.startsWith('http') || quote.startsWith('/api/') || quote.startsWith('figure://') || quote.startsWith('table://') || quote.startsWith('page://'));
  },

  showToast(msg, type, options) {
    const container = document.getElementById('toastContainer');
    if (!container) return;
    const toast = document.createElement('div');
    toast.className = 'toast toast-' + type;
    const opts = options || {};
    const bodyHtml = opts.html ? this.sanitizeHtml(opts.html) : this.escape(msg || '');
    toast.innerHTML = bodyHtml + '<span class="toast-close">&times;</span>';
    let actionBtn = null;
    if (opts.onAction) {
      actionBtn = toast.querySelector('[data-action]');
      if (actionBtn) actionBtn.addEventListener('click', opts.onAction);
    }
    const dismiss = () => {
      toast.classList.add('toast-out');
      setTimeout(() => {
        if (actionBtn) actionBtn.removeEventListener('click', opts.onAction);
        toast.remove();
      }, 250);
    };
    toast.querySelector('.toast-close').addEventListener('click', dismiss);
    container.appendChild(toast);
    const duration = opts.duration || (opts.persistent ? 0 : 6000);
    if (duration > 0) {
      setTimeout(() => {
        if (toast.parentNode) dismiss();
      }, duration);
    }
  },

  escape(s) { return (s || '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); },

  escapeHtml(s) { return (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); },

  escapeJsArg(value) {
    return this.escape(JSON.stringify(String(value ?? '')));
  },

  safeUrl(value, options = {}) {
    const { allowHash = true, allowRelative = true } = options;
    const raw = String(value || '').trim();
    if (!raw || /[�-<>"'`]/.test(raw)) return '';
    if (allowHash && raw.startsWith('#')) return raw;
    if (allowRelative && raw.startsWith('/') && !raw.startsWith('//')) return raw;
    try {
      const base = window.location ? window.location.origin : 'http://localhost';
      const url = new URL(raw, base);
      if (url.protocol !== 'http:' && url.protocol !== 'https:') return '';
      return raw;
    } catch (_) {
      return '';
    }
  },

  escapeUrlAttr(value, options) {
    const url = this.safeUrl(value, options);
    return url ? this.escape(url) : '';
  },

  sanitizeHtml(html) {
    if (!html) return '';
    const template = document.createElement('template');
    template.innerHTML = String(html);
    const allowedTags = new Set(['A', 'P', 'BR', 'STRONG', 'EM', 'B', 'I', 'CODE', 'PRE', 'BLOCKQUOTE', 'UL', 'OL', 'LI', 'TABLE', 'THEAD', 'TBODY', 'TR', 'TH', 'TD', 'HR', 'DIV', 'SPAN', 'IMG', 'H1', 'H2', 'H3', 'H4', 'H5', 'H6', 'DEL', 'S', 'SUP', 'SUB', 'BUTTON', 'MATH', 'SEMANTICS', 'MROW', 'MI', 'MN', 'MO', 'MS', 'MTEXT', 'ANNOTATION', 'MSPACE', 'MSUP', 'MSUB', 'MSUBSUP', 'MFRAC', 'MSQRT', 'MROOT', 'MTABLE', 'MTR', 'MTD', 'MPADDED', 'MUNDER', 'MOVER', 'MUNDEROVER', 'MSTYLE']);
    const allowedAttrs = new Set(['class', 'id', 'title', 'role', 'aria-label', 'aria-hidden', 'data-action', 'data-heading-num', 'data-latex', 'data-display', 'data-defer-prettier', 'data-full-src', 'alt', 'width', 'height', 'loading', 'decoding', 'colspan', 'rowspan', 'target', 'rel', 'type', 'xmlns', 'encoding', 'mathvariant', 'mathsize', 'stretchy', 'accent', 'accentunder', 'displaystyle', 'scriptlevel', 'rowspacing', 'columnalign', 'columnspacing']);
    const allowedStyleProps = new Set(['width', 'height', 'max-width', 'min-width', 'margin', 'margin-top', 'margin-right', 'margin-bottom', 'margin-left', 'text-align', 'float', 'vertical-align', 'font-size', 'font-weight', 'color', 'word-break', 'border', 'border-top', 'border-right', 'border-bottom', 'border-left', 'border-radius', 'background', 'background-color', 'padding', 'padding-top', 'padding-right', 'padding-bottom', 'padding-left', 'overflow-x', 'display', 'position', 'top', 'right', 'bottom', 'left']);
    const dangerousTags = new Set(['SCRIPT', 'STYLE', 'IFRAME', 'OBJECT', 'EMBED', 'LINK', 'META', 'BASE', 'FORM', 'INPUT', 'TEXTAREA', 'SELECT', 'OPTION']);
    const sanitizeStyle = (style) => String(style || '').split(';').map(part => {
      const idx = part.indexOf(':');
      if (idx <= 0) return '';
      const prop = part.slice(0, idx).trim().toLowerCase();
      const value = part.slice(idx + 1).trim();
      if (!allowedStyleProps.has(prop)) return '';
      if (/url\s*\(|expression\s*\(|javascript:|data:|[<>]/i.test(value)) return '';
      return prop + ':' + value;
    }).filter(Boolean).join(';');
    const unwrap = (el) => {
      const parent = el.parentNode;
      while (el.firstChild) parent.insertBefore(el.firstChild, el);
      el.remove();
    };
    const clean = (node) => {
      if (node.nodeType !== Node.ELEMENT_NODE) return;
      const tag = node.tagName;
      if (!allowedTags.has(tag)) {
        if (dangerousTags.has(tag)) {
          node.remove();
        } else {
          for (const child of Array.from(node.childNodes)) clean(child);
          unwrap(node);
        }
        return;
      }
      for (const attr of Array.from(node.attributes)) {
        const name = attr.name.toLowerCase();
        const value = attr.value;
        if (name.startsWith('on') || name === 'srcdoc') {
          node.removeAttribute(attr.name);
        } else if (name === 'href' || name === 'src' || name === 'data-full-src') {
          const safe = this.safeUrl(value, { allowHash: name === 'href' });
          if (safe) node.setAttribute(attr.name, safe);
          else node.removeAttribute(attr.name);
        } else if (name === 'style') {
          const safeStyle = sanitizeStyle(value);
          if (safeStyle) node.setAttribute('style', safeStyle);
          else node.removeAttribute('style');
        } else if (!allowedAttrs.has(name)) {
          node.removeAttribute(attr.name);
        }
      }
      if (tag === 'A') {
        const href = node.getAttribute('href') || '';
        if (href && !href.startsWith('#')) {
          node.setAttribute('target', '_blank');
          node.setAttribute('rel', 'noopener noreferrer');
        }
      }
      for (const child of Array.from(node.childNodes)) clean(child);
    };
    for (const child of Array.from(template.content.childNodes)) clean(child);
    return template.innerHTML;
  },

  isValidInsight(value) {
    const text = String(value || '');
    return !!text && text !== '__ANALYZING__' && !text.startsWith('Figure extraction failed') && !text.startsWith('Insight failed') && !text.startsWith('MinerU API not configured');
  },

  normalizePaper(p) {
    if (!p) return p;
    const paper = { ...p };
    if (!Array.isArray(paper.authors)) paper.authors = [];
    if (!Array.isArray(paper.tags)) paper.tags = [];
    if (paper.is_analyzing === undefined) paper.is_analyzing = paper.insight === '__ANALYZING__';
    if (paper.is_reviewing === undefined) paper.is_reviewing = paper.insight_review === '__REVIEWING__';
    if (paper.has_insight === undefined) paper.has_insight = this.isValidInsight(paper.insight);
    if (paper.has_review === undefined) paper.has_review = !!paper.insight_review && paper.insight_review !== '__REVIEWING__';
    return paper;
  },

  formatDate(iso) {
    if (!iso) return '-';
    const d = new Date(iso);
    if (isNaN(d)) return iso;
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    const h = String(d.getHours()).padStart(2, '0');
    const min = String(d.getMinutes()).padStart(2, '0');
    return `${y}-${m}-${day} ${h}:${min}`;
  },

  formatShortDate(iso) {
    if (!iso) return '-';
    const d = new Date(iso);
    if (isNaN(d)) return iso;
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${m}-${day}`;
  },

  /**
   * Trigger light haptic feedback on supported mobile devices.
   * @param {string} type - 'light' | 'medium' | 'heavy' | 'success'
   */
  haptic(type = 'light') {
    if (!window.navigator?.vibrate) return;
    const patterns = {
      light: 10,
      medium: 20,
      heavy: 30,
      success: [10, 50, 10],
    };
    try {
      navigator.vibrate(patterns[type] || patterns.light);
    } catch (_) {
      // ignore
    }
  },
};
